CREATE POLICY "Read accessible quote attachments" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'quote-attachments' AND EXISTS (SELECT 1 FROM public.quotes q WHERE q.id::text = (storage.foldername(name))[1]));
CREATE POLICY "Upload editable quote attachments" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'quote-attachments' AND EXISTS (SELECT 1 FROM public.quotes q WHERE q.id::text = (storage.foldername(name))[1] AND (public.has_role(auth.uid(), 'admin') OR EXISTS (SELECT 1 FROM public.customers c JOIN public.salespeople s ON s.id = c.assigned_salesperson_id WHERE c.id = q.customer_id AND s.user_id = auth.uid()))));